const item = $input.first().json || {};
const headers = item.headers || {};
const got = String(headers['x-internal-secret'] || headers['X-Internal-Secret'] || '').trim();
const expected = String($env.INTERNAL_WEBHOOK_SECRET || '').trim();
if (!expected || got !== expected) {
  throw new Error('Unauthorized');
}
const body = item.body && typeof item.body === 'object' ? item.body : item;
const system = String(body.system || '').trim();
const messages = Array.isArray(body.messages) ? body.messages : [];
if (!system && !messages.length) {
  throw new Error('system or messages is required');
}
const openrouterMessages = [];
if (system) openrouterMessages.push({ role: 'system', content: system });
for (const message of messages) {
  if (!message || (message.role !== 'user' && message.role !== 'assistant' && message.role !== 'system')) continue;
  const content = String(message.content || '').trim();
  if (!content) continue;
  openrouterMessages.push({ role: message.role, content });
}
if (!openrouterMessages.length) {
  throw new Error('No valid messages');
}
return [{ json: { openrouterMessages } }];

function messageText(message) {
  if (!message) return '';
  const content = message.content;
  if (typeof content === 'string') return content.trim();
  if (Array.isArray(content)) {
    return content.map((part) => {
      if (typeof part === 'string') return part;
      if (part && typeof part.text === 'string') return part.text;
      return '';
    }).join('').trim();
  }
  return '';
}
const item = $input.first().json || {};
if (item.error) {
  return [{ json: { ok: false, error: (item.error.message || item.error.description || 'NVIDIA Nemotron Ultra request failed') } }];
}
const answer = messageText(item.choices && item.choices[0] && item.choices[0].message);
if (!answer) {
  return [{ json: { ok: false, error: 'NVIDIA Nemotron Ultra returned empty answer' } }];
}
return [{ json: { ok: true, answer, model: 'nvidia' } }];
